// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SourceObservation) predicate.SourceObservation {
	return predicate.SourceObservation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SourceObservation) predicate.SourceObservation {
	return predicate.SourceObservation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SourceObservation) predicate.SourceObservation {
	return predicate.SourceObservation(sql.NotPredicates(p))
}
